     1|/**
     2| * IVX Senior-Developer QA-ONLY Runtime
     3| *
     4| * FINAL CERTIFICATION FIX (owner 2026-07-20):
     5| *   QA-only requests ("Run QA on the IVX Chat module without modifying code")
     6| *   created a persistent worker job but did NOT execute relevant module tests.
     7| *
     8| * This runtime runs the SAME persistent worker-job infrastructure as the
     9| * developer_executor, but in a strictly QA-ONLY mode:
    10| *
    11| *   PERMITTED:  inspect repository files, identify relevant test files,
    12| *               run targeted `bun test` for the matched module, run scoped
    13| *               typecheck, run lint when applicable, capture exit codes +
    14| *               pass/fail/skip counts + duration, return structured evidence.
    15| *
    16| *   BLOCKED:    editing files, committing, pushing, deploying, applying
    17| *               migrations, changing production data.
    18| *
    19| * Output format (owner-mandated):
    20| *
    21| *   TASK ID / MODE: QA_ONLY / FILES INSPECTED / TESTS SELECTED / COMMANDS RUN /
    22| *   EXIT CODES / PASSED / FAILED / SKIPPED / TYPECHECK / LINT / FINDINGS / STATUS
    23| *
    24| * When the target module cannot be identified, returns:
    25| *   STATUS: BLOCKED / ERROR CODE: QA_TARGET_NOT_FOUND
    26| */
    27|import { createHash } from 'node:crypto';
    28|import { readdir, readFile, stat } from 'node:fs/promises';
    29|import path from 'node:path';
    30|import { fileURLToPath } from 'node:url';
    31|
    32|export const IVX_QA_ONLY_MARKER = 'ivx-senior-developer-qa-only-2026-07-20';
    33|
    34|/** QA-only execution mode flag carried on the worker job input. */
    35|export type IVXQAOnlyExecutionMode = 'qa_only';
    36|
    37|/** A command executed during the QA run. */
    38|export type IVXQACommand = {
    39|  command: string;
    40|  /** "run_tests" | "typecheck" | "lint" | "stat" */
    41|  kind: 'run_tests' | 'typecheck' | 'lint' | 'stat';
    42|  ok: boolean;
    43|  exitCode: number | null;
    44|  outputPreview: string;
    45|  error: string | null;
    46|  durationMs: number;
    47|};
    48|
    49|/** A test file selected for the QA run. */
    50|export type IVXQATestFile = {
    51|  path: string;
    52|  bytes: number;
    53|};
    54|
    55|/** A file inspected during the QA run. */
    56|export type IVXQAInspectedFile = {
    57|  path: string;
    58|  bytes: number;
    59|  preview: string;
    60|};
    61|
    62|export type IVXQAOnlyProof = {
    63|  marker: typeof IVX_QA_ONLY_MARKER;
    64|  jobId: string;
    65|  goal: string;
    66|  mode: IVXQAOnlyExecutionMode;
    67|  finalStatus: 'COMPLETED' | 'BLOCKED' | 'FAILED';
    68|  patchApplied: boolean;
    69|  commitCreated: boolean;
    70|  deployed: boolean;
    71|  changedFiles: string[];
    72|  filesInspected: IVXQAInspectedFile[];
    73|  testsSelected: IVXQATestFile[];
    74|  commandsRun: IVXQACommand[];
    75|  passed: number;
    76|  failed: number;
    77|  skipped: number;
    78|  typecheckOk: boolean | null;
    79|  lintOk: boolean | null;
    80|  findings: string;
    81|  errorCode: string | null;
    82|  error: string | null;
    83|  generatedAt: string;
    84|  secretValuesReturned: false;
    85|};
    86|
    87|export type IVXQAOnlyPhase =
    88|  | 'queued'
    89|  | 'module_identified'
    90|  | 'files_inspected'
    91|  | 'tests_selected'
    92|  | 'tests_executed'
    93|  | 'typecheck_run'
    94|  | 'lint_run'
    95|  | 'completed'
    96|  | 'blocked'
    97|  | 'failed';
    98|
    99|export type IVXQAOnlyRunInput = {
   100|  goal: string;
   101|  onPhase?: (phase: IVXQAOnlyPhase, detail: string) => void;
   102|};
   103|
   104|/** Dirs to search for test files. */
   105|const QA_TEST_ROOTS = ['backend', 'expo/__tests__'];
   106|
   107|/** Dirs never searched. */
   108|const QA_IGNORED_DIRS = new Set([
   109|  '.git', '.rork', 'node_modules', '.expo', 'dist', 'build', 'coverage',
   110|  'logs', 'tmp', '__mocks__', 'mocks',
   111|]);
   112|
   113|const MAX_INSPECTED_FILES = 16;
   114|const MAX_TEST_FILES = 12;
   115|const FILE_PREVIEW_CHARS = 160;
   116|const COMMAND_OUTPUT_PREVIEW_CHARS = 1200;
   117|const COMMAND_TIMEOUT_MS = 50_000;
   118|
   119|function nowIso(): string {
   120|  return new Date().toISOString();
   121|}
   122|
   123|function safeErrorMessage(error: unknown): string {
   124|  return error instanceof Error ? error.message.slice(0, 500) : 'Unknown QA runtime error.';
   125|}
   126|
   127|function truncate(value: string, max: number): string {
   128|  if (value.length <= max) return value;
   129|  return `${value.slice(0, max - 3)}...`;
   130|}
   131|
   132|/**
   133| * Extract module keywords from the goal. Converts natural-language module
   134| * references ("IVX Chat module", "senior developer module", "factory engine")
   135| * into kebab-case keywords for test-file path matching.
   136| */
   137|function extractModuleKeywords(goal: string): string[] {
   138|  const normalized = goal.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
   139|  const words = normalized.split(' ').filter((w) => w.length >= 3);
   140|
   141|  // Filter out common non-module words
   142|  const stopWords = new Set([
   143|    'the', 'and', 'for', 'that', 'this', 'with', 'from', 'have', 'please',
   144|    'report', 'change', 'deploy', 'anything', 'current', 'status', 'without',
   145|    'modifying', 'code', 'module', 'run', 'regression', 'sweep', 'check',
   146|    'verify', 'verification', 'test', 'tests', 'suite', 'typecheck', 'tsc',
   147|    'lint', 'pass', 'fail', 'skipped', 'low', 'risk', 'defect', 'one',
   148|    'prepare', 'commit', 'but', 'not', 'all', 'end', 'make', 'sure',
   149|    'working', 'enterprise', 'business', 'give', 'me', 'show', 'proof',
   150|    'evidence', 'live', 'now', 'need', 'want', 'you', 'can', 'are',
   151|    'yes', 'fix', 'inspect', 'only', 'just', 'pre', 'post', 'submission',
   152|    'flight', 'smoke', 'quality', 'assurance', 'about', 'tell', 'about',
   153|  ]);
   154|
   155|  const keywords = words.filter((w) => !stopWords.has(w));
   156|
   157|  // Also add compound kebab-case keywords for multi-word module names
   158|  const compoundMap: Record<string, string> = {
   159|    'ivx chat': 'chat',
   160|    'chat ordering': 'chat',
   161|    'chat message': 'chat',
   162|    'senior developer': 'senior-developer',
   163|    'factory engine': 'factory',
   164|    'autonomous coder': 'autonomous-coder',
   165|    'execution mode': 'execution-mode',
   166|    'reliability gate': 'reliability-gate',
   167|    'owner ai': 'owner-ai',
   168|    'completion validator': 'completion-validator',
   169|    'task state': 'task-state',
   170|    'context pipeline': 'context-pipeline',
   171|    'duplicate worker': 'duplicate-worker',
   172|    'chat pagination': 'chat-pagination',
   173|    'real data': 'real-data',
   174|    'engineering os': 'engineering-os',
   175|    'executive layer': 'executive-layer',
   176|    'capital pipeline': 'capital-pipeline',
   177|    'deal tracking': 'deal-tracking',
   178|    'investor crm': 'investor-crm',
   179|  };
   180|  for (const [phrase, keyword] of Object.entries(compoundMap)) {
   181|    if (normalized.includes(phrase)) {
   182|      keywords.push(keyword);
   183|    }
   184|  }
   185|
   186|  return Array.from(new Set(keywords));
   187|}
   188|
   189|/**
   190| * Walk test file directories and return all .test.ts files.
   191| */
   192|async function walkTestFiles(projectRoot: string): Promise<string[]> {
   193|  const results: string[] = [];
   194|  async function visit(relDir: string): Promise<void> {
   195|    if (results.length >= 200) return;
   196|    const absDir = path.join(projectRoot, relDir);
   197|    let entries: string[];
   198|    try {
   199|      entries = await readdir(absDir);
   200|    } catch {
   201|      return;
   202|    }
   203|    for (const entry of entries) {
   204|      const relEntry = relDir ? `${relDir}/${entry}` : entry;
   205|      const absEntry = path.join(absDir, entry);
   206|      let info;
   207|      try {
   208|        info = await stat(absEntry);
   209|      } catch {
   210|        continue;
   211|      }
   212|      if (info.isDirectory()) {
   213|        if (QA_IGNORED_DIRS.has(entry)) continue;
   214|        // Only descend into backend/ and expo/__tests__/
   215|        if (relDir === '' && entry !== 'backend' && entry !== 'expo') continue;
   216|        if (relDir === 'expo' && entry !== '__tests__') continue;
   217|        await visit(relEntry);
   218|      } else if (info.isFile() && entry.endsWith('.test.ts')) {
   219|        results.push(relEntry);
   220|      }
   221|    }
   222|  }
   223|  for (const root of QA_TEST_ROOTS) {
   224|    await visit(root);
   225|  }
   226|  return results;
   227|}
   228|
   229|/**
   230| * Match test files against the module keywords. Returns the test files
   231| * whose paths contain any of the kebab-case keywords.
   232| */
   233|function selectTestFiles(keywords: string[], allTestFiles: string[]): IVXQATestFile[] {
   234|  if (keywords.length === 0) return [];
   235|  const kebabKeywords = keywords.map((k) => k.replace(/\s+/g, '-'));
   236|  const matched = allTestFiles.filter((file) => {
   237|    const lower = file.toLowerCase();
   238|    return kebabKeywords.some((kw) => lower.includes(kw));
   239|  });
   240|  return matched.slice(0, MAX_TEST_FILES).map((file) => ({
   241|    path: file,
   242|    bytes: 0, // filled lazily during inspection
   243|  }));
   244|}
   245|
   246|/**
   247| * Inspect source files related to the module (non-test files matching keywords).
   248| */
   249|async function inspectSourceFiles(
   250|  projectRoot: string,
   251|  keywords: string[],
   252|  allTestFiles: string[],
   253|): Promise<IVXQAInspectedFile[]> {
   254|  const kebabKeywords = keywords.map((k) => k.replace(/\s+/g, '-'));
   255|  const inspected: IVXQAInspectedFile[] = [];
   256|
   257|  // Walk backend/ and expo/ for .ts/.tsx source files matching keywords
   258|  const sourceFiles: string[] = [];
   259|  async function visit(relDir: string): Promise<void> {
   260|    if (sourceFiles.length >= 100) return;
   261|    const absDir = path.join(projectRoot, relDir);
   262|    let entries: string[];
   263|    try {
   264|      entries = await readdir(absDir);
   265|    } catch {
   266|      return;
   267|    }
   268|    for (const entry of entries) {
   269|      const relEntry = relDir ? `${relDir}/${entry}` : entry;
   270|      const absEntry = path.join(absDir, entry);
   271|      let info;
   272|      try {
   273|        info = await stat(absEntry);
   274|      } catch {
   275|        continue;
   276|      }
   277|      if (info.isDirectory()) {
   278|        if (QA_IGNORED_DIRS.has(entry)) continue;
   279|        if (relDir === '' && entry !== 'backend' && entry !== 'expo') continue;
   280|        await visit(relEntry);
   281|      } else if (info.isFile() && (entry.endsWith('.ts') || entry.endsWith('.tsx')) && !entry.endsWith('.test.ts')) {
   282|        const lower = relEntry.toLowerCase();
   283|        if (kebabKeywords.some((kw) => lower.includes(kw))) {
   284|          sourceFiles.push(relEntry);
   285|        }
   286|      }
   287|    }
   288|  }
   289|  await visit('backend');
   290|  await visit('expo');
   291|
   292|  for (const file of sourceFiles.slice(0, MAX_INSPECTED_FILES)) {
   293|    try {
   294|      const absPath = path.join(projectRoot, file);
   295|      const content = await readFile(absPath, 'utf8');
   296|      inspected.push({
   297|        path: file,
   298|        bytes: Buffer.byteLength(content, 'utf8'),
   299|        preview: truncate(content.replace(/\r/g, '').trimStart(), FILE_PREVIEW_CHARS),
   300|      });
   301|    } catch {
   302|      // skip unreadable files
   303|    }
   304|  }
   305|  return inspected;
   306|}
   307|
   308|/**
   309| * Run a shell command and capture stdout/stderr/exitCode.
   310| */
   311|async function runCommand(
   312|  projectRoot: string,
   313|  command: string,
   314|  kind: IVXQACommand['kind'],
   315|): Promise<IVXQACommand> {
   316|  const startedAt = Date.now();
   317|  try {
   318|    const { spawn } = await import('node:child_process') as typeof import('node:child_process');
   319|    const parts = command.split(' ');
   320|    const child = spawn(parts[0], parts.slice(1), {
   321|      cwd: projectRoot,
   322|      env: { ...process.env, CI: 'true', FORCE_COLOR: '0' },
   323|      stdio: ['ignore', 'pipe', 'pipe'],
   324|      timeout: COMMAND_TIMEOUT_MS,
   325|    });
   326|    let stdout = '';
   327|    let stderr = '';
   328|    child.stdout?.on('data', (chunk: Buffer) => {
   329|      stdout += chunk.toString();
   330|      if (stdout.length > 8192) stdout = stdout.slice(-8192);
   331|    });
   332|    child.stderr?.on('data', (chunk: Buffer) => {
   333|      stderr += chunk.toString();
   334|      if (stderr.length > 4096) stderr = stderr.slice(-4096);
   335|    });
   336|    const exitCode = await new Promise<number>((resolve) => {
   337|      child.on('close', (code) => resolve(typeof code === 'number' ? code : 0));
   338|      child.on('error', () => resolve(1));
   339|    });
   340|    const preview = truncate(
   341|      (stdout + (stderr ? `\n[stderr]\n${stderr}` : '')).trim(),
   342|      COMMAND_OUTPUT_PREVIEW_CHARS,
   343|    );
   344|    return {
   345|      command,
   346|      kind,
   347|      ok: exitCode === 0,
   348|      exitCode,
   349|      outputPreview: preview,
   350|      error: exitCode === 0 ? null : `exit ${exitCode}`,
   351|      durationMs: Date.now() - startedAt,
   352|    };
   353|  } catch (error) {
   354|    return {
   355|      command,
   356|      kind,
   357|      ok: false,
   358|      exitCode: null,
   359|      outputPreview: '',
   360|      error: safeErrorMessage(error),
   361|      durationMs: Date.now() - startedAt,
   362|    };
   363|  }
   364|}
   365|
   366|/**
   367| * Parse bun test output for pass/fail/skip counts.
   368| * Bun test output format: "  1698 pass\n  0 fail\n  6190 expect() calls\nRan 1698 tests across 122 files. [2.83s]"
   369| */
   370|function parseTestCounts(output: string): { passed: number; failed: number; skipped: number } {
   371|  const passMatch = output.match(/(\d+)\s+pass/i);
   372|  const failMatch = output.match(/(\d+)\s+fail/i);
   373|  const skipMatch = output.match(/(\d+)\s+(?:skip|skipped|todo)/i);
   374|  return {
   375|    passed: passMatch ? parseInt(passMatch[1], 10) : 0,
   376|    failed: failMatch ? parseInt(failMatch[1], 10) : 0,
   377|    skipped: skipMatch ? parseInt(skipMatch[1], 10) : 0,
   378|  };
   379|}
   380|
   381|/**
   382| * Run a QA-only inspection through the persistent worker pipeline. Returns
   383| * a structured proof the worker writes to the durable ledger. NEVER edits,
   384| * commits, pushes, deploys, or applies migrations.
   385| */
   386|export async function runIVXQAOnly(
   387|  input: IVXQAOnlyRunInput,
   388|): Promise<IVXQAOnlyProof> {
   389|  const goal = input.goal.trim();
   390|  if (!goal) throw new Error('A QA-only goal is required.');
   391|
   392|  const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
   393|  const jobId = `ivx-qa-${createHash('sha1').update(`${goal}:${Date.now()}`).digest('hex').slice(0, 12)}`;
   394|  const onPhase = input.onPhase;
   395|  const commandsRun: IVXQACommand[] = [];
   396|
   397|  onPhase?.('queued', 'QA-only run queued.');
   398|
   399|  // Step 1: Extract module keywords from the goal
   400|  const keywords = extractModuleKeywords(goal);
   401|  onPhase?.('module_identified', `Module keywords: ${keywords.join(', ') || '(none)'}`);
   402|
   403|  // Step 2: Walk all test files
   404|  const allTestFiles = await walkTestFiles(projectRoot);
   405|
   406|  // Step 3: Select test files matching the module keywords
   407|  const testFiles = selectTestFiles(keywords, allTestFiles);
   408|
   409|  if (testFiles.length === 0) {
   410|    // No test files matched — return BLOCKED with QA_TARGET_NOT_FOUND
   411|    onPhase?.('blocked', 'No test files matched the module keywords.');
   412|    const proof: IVXQAOnlyProof = {
   413|      marker: IVX_QA_ONLY_MARKER,
   414|      jobId,
   415|      goal,
   416|      mode: 'qa_only',
   417|      finalStatus: 'BLOCKED',
   418|      patchApplied: false,
   419|      commitCreated: false,
   420|      deployed: false,
   421|      changedFiles: [],
   422|      filesInspected: [],
   423|      testsSelected: [],
   424|      commandsRun: [],
   425|      passed: 0,
   426|      failed: 0,
   427|      skipped: 0,
   428|      typecheckOk: null,
   429|      lintOk: null,
   430|      findings: `No test files could be identified for the requested module. Keywords extracted: ${keywords.join(', ') || '(none)'}. Available test files: ${allTestFiles.length}.`,
   431|      errorCode: 'QA_TARGET_NOT_FOUND',
   432|      error: null,
   433|      generatedAt: nowIso(),
   434|      secretValuesReturned: false,
   435|    };
   436|    onPhase?.('blocked', 'QA_TARGET_NOT_FOUND — no test files matched.');
   437|    return proof;
   438|  }
   439|
   440|  onPhase?.('tests_selected', `Selected ${testFiles.length} test file(s): ${testFiles.map((t) => t.path).join(', ')}`);
   441|
   442|  // Step 4: Inspect source files related to the module
   443|  const filesInspected = await inspectSourceFiles(projectRoot, keywords, allTestFiles);
   444|  onPhase?.('files_inspected', `Inspected ${filesInspected.length} source file(s).`);
   445|
   446|  // Step 5: Run targeted tests
   447|  const testFilePaths = testFiles.map((t) => t.path).join(' ');
   448|  const testCommand = `bun test ${testFilePaths}`;
   449|  const testResult = await runCommand(projectRoot, testCommand, 'run_tests');
   450|  commandsRun.push(testResult);
   451|  const counts = parseTestCounts(testResult.outputPreview);
   452|  onPhase?.('tests_executed', `Tests executed: ${counts.passed} pass, ${counts.failed} fail, ${counts.skipped} skip (exit ${testResult.exitCode}).`);
   453|
   454|  // Step 6: Run scoped typecheck
   455|  const typecheckCommand = 'bun x tsc --noEmit --skipLibCheck';
   456|  const typecheckResult = await runCommand(projectRoot, typecheckCommand, 'typecheck');
   457|  commandsRun.push(typecheckResult);
   458|  onPhase?.('typecheck_run', `Typecheck: exit ${typecheckResult.exitCode}.`);
   459|
   460|  // Step 7: Run lint (if eslint config exists, skip gracefully if not)
   461|  let lintResult: IVXQACommand | null = null;
   462|  try {
   463|    const eslintConfig = await stat(path.join(projectRoot, '.eslintrc.cjs')).catch(() =>
   464|      stat(path.join(projectRoot, '.eslintrc.js')).catch(() => null),
   465|    );
   466|    if (eslintConfig) {
   467|      lintResult = await runCommand(projectRoot, 'bun x eslint --max-warnings 0 backend/services/ backend/api/', 'lint');
   468|      commandsRun.push(lintResult);
   469|      onPhase?.('lint_run', `Lint: exit ${lintResult.exitCode}.`);
   470|    } else {
   471|      onPhase?.('lint_run', 'Lint: skipped (no eslint config found).');
   472|    }
   473|  } catch {
   474|    onPhase?.('lint_run', 'Lint: skipped (no eslint config found).');
   475|  }
   476|
   477|  // Step 8: Build findings
   478|  const findings = [
   479|    `Module keywords: ${keywords.join(', ')}`,
   480|    `Test files selected: ${testFiles.length} (${testFiles.map((t) => t.path).join(', ')})`,
   481|    `Tests: ${counts.passed} passed, ${counts.failed} failed, ${counts.skipped} skipped (exit code ${testResult.exitCode})`,
   482|    `Typecheck: ${typecheckResult.ok ? 'PASS' : 'FAIL'} (exit code ${typecheckResult.exitCode})`,
   483|    lintResult ? `Lint: ${lintResult.ok ? 'PASS' : 'FAIL'} (exit code ${lintResult.exitCode})` : 'Lint: not run (no eslint config)',
   484|    `Source files inspected: ${filesInspected.length}`,
   485|    `Files changed: 0 (QA-only mode never modifies code)`,
   486|    `Commit: not requested (QA-only mode never commits)`,
   487|    `Deploy: not requested (QA-only mode never deploys)`,
   488|  ].join('\n');
   489|
   490|  const finalStatus: IVXQAOnlyProof['finalStatus'] = testResult.ok ? 'COMPLETED' : 'FAILED';
   491|
   492|  const proof: IVXQAOnlyProof = {
   493|    marker: IVX_QA_ONLY_MARKER,
   494|    jobId,
   495|    goal,
   496|    mode: 'qa_only',
   497|    finalStatus,
   498|    patchApplied: false,
   499|    commitCreated: false,
   500|    deployed: false,
   501|    changedFiles: [],
   502|    filesInspected,
   503|    testsSelected: testFiles,
   504|    commandsRun,
   505|    passed: counts.passed,
   506|    failed: counts.failed,
   507|    skipped: counts.skipped,
   508|    typecheckOk: typecheckResult.ok,
   509|    lintOk: lintResult ? lintResult.ok : null,
   510|    findings,
   511|    errorCode: null,
   512|    error: null,
   513|    generatedAt: nowIso(),
   514|    secretValuesReturned: false,
   515|  };
   516|
   517|  onPhase?.('completed', `QA-only run completed. ${counts.passed} pass / ${counts.failed} fail / ${counts.skipped} skip.`);
   518|  return proof;
   519|}
   520|
   521|/**
   522| * Render the owner-mandated strict QA-only format.
   523| *
   524| *   TASK ID / MODE: QA_ONLY / FILES INSPECTED / TESTS SELECTED / COMMANDS RUN /
   525| *   EXIT CODES / PASSED / FAILED / SKIPPED / TYPECHECK / LINT / FINDINGS / STATUS
   526| */
   527|export function buildQAOnlyAnswer(proof: IVXQAOnlyProof): string {
   528|  if (proof.errorCode === 'QA_TARGET_NOT_FOUND') {
   529|    return [
   530|      `TASK ID:\n${proof.jobId}`,
   531|      'MODE:\nQA_ONLY',
   532|      'FILES INSPECTED:\nNONE — no module could be identified.',
   533|      'TESTS SELECTED:\nNONE — no test files matched the requested module.',
   534|      'COMMANDS RUN:\nNONE',
   535|      'EXIT CODES:\nN/A',
   536|      'PASSED:\n0',
   537|      'FAILED:\n0',
   538|      'SKIPPED:\n0',
   539|      'TYPECHECK:\nNOT RUN',
   540|      'LINT:\nNOT RUN',
