export type WatchdogSuccessResult = {
  status: 'completed';
  command: string;
  exitCode: number;
  signal: null;
  startedAt: string;
  endedAt: string;
  stdoutTail: string;
  stderrTail: string;
  timedOut: false;
};

export type WatchdogFailureResult = {
  status: 'failed';
  command: string;
  exitCode: number;
  signal: null;
  startedAt: string;
  endedAt: string;
