  stderrTail: string;
  timedOut: false;
};

export type WatchdogSpawnErrorResult = {
  status: 'spawn_error';
  command: string;
  exitCode: null;
  signal: null;
  startedAt: string;
  endedAt: string;
  stdoutTail: string;
  stderrTail: string;
  error: string;
